columnDataChange.newValue:
async (process, view) => {
  const HIDE_POPUP_PROPERTY = 'APRM_MATCHSTATEMENT_HIDE_PARTIALMATCH_POPUP';
  const NO_RECORD_LABEL = 'APRM_SELECT_RECORD_ERROR';
  const SPLIT_CONFIRM_LABEL = 'APRM_SplitBankStatementLineConfirm';

  const formatAmount = (amount) =>
    OB.Utilities.Number.JSToOBMasked(
      amount,
      OB.Format.defaultNumericMask,
      OB.Format.defaultDecimalSymbol,
      OB.Format.defaultGroupingSymbol,
      OB.Format.defaultGroupingSize
    );

  const contextInfo = view.getContextInfo();
  const trxParameter = contextInfo && contextInfo.findtransactiontomatch;
  const trxSelection = trxParameter && trxParameter._selection;

  if (!trxSelection || !trxSelection[0]) {
    view.messageBar.setMessage(
      isc.OBMessageBar.TYPE_ERROR,
      null,
      OB.I18N.getLabel(NO_RECORD_LABEL)
    );
    return { severity: 'error', text: OB.I18N.getLabel(NO_RECORD_LABEL) };
  }

  const blineAmt = new BigDecimal(String(view.callerField.record.amount));
  let totalTrxAmt = BigDecimal.prototype.ZERO;
  for (const trx of trxSelection) {
    const trxDepositAmt = new BigDecimal(String(trx.depositAmount));
    const trxPaymentAmt = new BigDecimal(String(trx.paymentAmount));
    totalTrxAmt = totalTrxAmt.add(trxDepositAmt.subtract(trxPaymentAmt));
  }

  const splitRequired = totalTrxAmt.compareTo(blineAmt) !== 0;
  if (!splitRequired) {
    return (await view.executeProcess())?.message;
  }

  const hideSplitConfirmation =
    OB.PropertyStore.get(HIDE_POPUP_PROPERTY, view.windowId) === 'Y';
  if (hideSplitConfirmation) {
    return (await view.executeProcess())?.message;
  }

  const confirmed = await confirm(
    OB.I18N.getLabel(SPLIT_CONFIRM_LABEL, [
      formatAmount(blineAmt),
      formatAmount(totalTrxAmt)
    ])
  );
  if (!confirmed) {
    return { severity: 'error', text: '' };
  }
  return (await view.executeProcess())?.message;
}

async (process, view) => {
  const accountsGrid = () => view.theForm.getItem(ACCOUNTS_PARAM).canvas.viewGrid;

  accountsGrid().hide();

  OB.Utilities.Action.set('showVATGrid', () => {
    accountsGrid().show();
  });

  OB.Utilities.Action.set('updateVATTotal', (paramObj) => {
    view.theForm.getItem(AMOUNT_PARAM).setValue(paramObj.amount);
  });

  OB.Utilities.Action.set('updateVATLines', (paramObj) => {
    state.lines = paramObj;
  });
}

const ACCOUNTS_PARAM = 'Accounts';
const AMOUNT_PARAM = 'amount';
const AMOUNT_COLUMN = 'amt';

const state = { lines: null };

const sumAccountAmount = (rowId) => {
  const lines = state.lines;
  if (!lines || !Array.isArray(lines.accounts)) {
    return null;
  }
  const matching = lines.accounts.filter((account) => account.id === rowId);
  if (matching.length === 0) {
    return null;
  }
  return matching.reduce((total, account) => total + parseFloat(account.amt), 0);
};

return { ACCOUNTS_PARAM, AMOUNT_PARAM, AMOUNT_COLUMN, state, sumAccountAmount };

(_process, view) => {
  const INVOICE_DEFAULTS_HANDLER = 'com.smf.jobs.defaults.ProcessInvoicesDefaults';
  const INVOICE_TABLE_ID = '318';
  const form = view.theForm;
  const docActionField = form.getItem('DocAction');
  const voidDateField = form.getItem('VoidDate');
  const voidAcctDateField = form.getItem('VoidAccountingDate');
  const supplierReferenceField = form.getItem('POReference');
  const selectedRecords = view.selectedRecords || [];
  const documentStatuses = [];
  const documentActions = [];

  for (let i = 0; i < selectedRecords.length; i++) {
    const record = selectedRecords[i];
    if (!documentStatuses.includes(record.documentStatus)) {
      documentStatuses.push(record.documentStatus);
    }
    if (!documentActions.includes(record.documentAction)) {
      documentActions.push(record.documentAction);
    }
  }

  voidDateField.hide();
  voidAcctDateField.hide();
  supplierReferenceField.hide();

  OB.RemoteCallManager.call(
    INVOICE_DEFAULTS_HANDLER,
    { documentStatuses: documentStatuses, isProcessing: '', tableId: INVOICE_TABLE_ID },
    {},
    (response, data, request) => {
      const actions = data.actions || [];
      const currentValues = docActionField.getValueMap();
      const newValues = {};

      for (let i = 0; i < actions.length; i++) {
        const action = actions[i];
        const match = currentValues.find((option) => option.value === action || option.id === action);
        if (match) {
          newValues[action] = match.label;
        }
      }

      docActionField.setValueMap(newValues);
      // Avoid setting an action that is on the record(s) but not in the dropdown list.
      if (newValues[documentActions[0]]) {
        docActionField.setValueProgrammatically(documentActions[0]);
      } else {
        docActionField.setValueProgrammatically(docActionField.getFirstOptionValue());
      }
    }
  );
}

async (process, view) => {
  const records = view.hookData.selectedRecords ?? [];
  if (records.length === 0) {
    return { error: { msgText: OB.I18N.getLabel("OBUIAPP_NoSelectedRecords"), msgType: "error" } };
  }
  return await runSiiAction(records);
}

// @module-scope
// Shared helper mirroring the classic OB.AEATSII.execute (ModDefinicionProceso.js:14):
// one remote call, the server's own severity/title/text in the banner, then a grid
// refresh. Cloned per process because payscript module scope is per-process.
const ACTION_HANDLER = "org.openbravo.module.sii.process.MultiEnvioFactura";
const WARNING_LABEL = "AEATSII_WARNING_SEND";
const TITLE_LABEL = "AEATSII_TITLE_SEND";

const runSiiAction = async (records) => {
  const confirmed = await confirm(OB.I18N.getLabel(WARNING_LABEL), {
    title: OB.I18N.getLabel(TITLE_LABEL),
  });
  // Classic closes the popup and runs nothing when the user declines.
  if (!confirmed) return { type: "closeModal" };

  const response = await callAction(ACTION_HANDLER, {
    ids: records.map((record) => record.id),
    orgid: records[0].organization,
  });

  const message = response?.data?.message ?? {};
  return {
    message: { msgType: message.severity, msgTitle: message.title, msgText: message.text },
    responseActions: [{ refreshGrid: {} }],
  };
};

return { runSiiAction };

async (process, view) => {
  const PRECHECK_HANDLER = "org.openbravo.costing.CostingRuleProcessOnProcessHandler";
  const EXECUTE_HANDLER = "org.openbravo.costing.CostingRuleProcessActionHandler";
  view.messageBar.setMessage("info", null, OB.I18N.getLabel("CostingRuleHelp"));
  const ruleId = view.recordIds && view.recordIds[0];
  const runExecution = async () => {
    const response = await callAction(EXECUTE_HANDLER, { M_Costing_Rule_ID: ruleId }, { queryParams: { processId: process.id } });
    return response.data && response.data.message;
  };
  const precheck = await callAction(PRECHECK_HANDLER, { ruleId });
  const precheckMessage = precheck.data && precheck.data.message;
  const confirmText = precheckMessage && precheckMessage.text;
  if (!confirmText) {
    return await runExecution();
  }
  const accepted = await confirm(confirmText);
  if (!accepted) {
    return { severity: "info", text: "" };
  }
  return await runExecution();
}

// @module-scope
const EAPM_POPUP_ACTION = "EAPM_Popup";
const SECOND_HANDLER = "com.etendoerp.advpaymentmngt.actionHandler.PaymentExecutionProcessActionHandler";
const PAYMENT_PICK_GRID = "payment_pick";
const SEVERITY_SUCCESS = "success";
const SEVERITY_ERROR = "error";
const GENERIC_ERROR = "Error executing the process";

const refreshPaymentGrid = () => {
  OB.Utilities.Action.executeJSON([{ refreshGrid: {} }, { refreshGridParameter: { gridName: PAYMENT_PICK_GRID } }]);
};

const handleExecutionResponse = (data) => {
  if (!data) {
    messageBar.setMessage(SEVERITY_ERROR, null, GENERIC_ERROR);
    return;
  }
  if (data.success) {
    refreshPaymentGrid();
    messageBar.setMessage(SEVERITY_SUCCESS, null, data.message);
  } else {
    messageBar.setMessage(SEVERITY_ERROR, null, data.error || GENERIC_ERROR);
  }
};

OB.Utilities.Action.set(EAPM_POPUP_ACTION, async (actionData) => {
  const collected = await openDynamicForm({
    title: actionData.executionProcessName,
    fields: actionData.processParameters,
  });
  if (!collected) {
    return;
  }
  OB.RemoteCallManager.call(
    SECOND_HANDLER,
    { _params: actionData, processParameters: collected },
    {},
    (rpcResponse, data) => handleExecutionResponse(data)
  );
});

return {};

