columnDataChange.oldValue:
async (_processDefinition, { selectedRecords, parentRecord }) => {
  let initialTotalPay = 0;


  // Add if there are already records selected by default
  if (selectedRecords && selectedRecords.length > 0) {
    for (let i = 0; i < selectedRecords.length; i++) {
        const payment = selectedRecords[i].realpayment || selectedRecords[i].realPayment || 0;
        initialTotalPay += parseFloat(payment);
    }
  }

  // Extract the dueDate from the parent record
  const remittanceDueDate = parentRecord?.inpduedate || parentRecord?.dueDate;

  // Initial Payload
  const loadPayload = {
    "total count": initialTotalPay
  };

  // Map the injected Criteria in onLoadGrid (expectedDate <= remittanceDueDate)
  if (remittanceDueDate) {
    // The grid in the parameter definition is called "pending payments" (dBColumnName)
    const gridKey = "pending payments";
    console.log("gridKey: ", gridKey);

    loadPayload._filterExpressions = {
      [gridKey]: {
        expectedDate: {
          operator: "lessOrEqual",
          value: `To - ${remittanceDueDate}`
        }
      }
    };
  }

  return loadPayload;
}

columnDataChange.newValue:
async (process, view) => {
  const GRID_KEY = 'pending payments';
  const remittanceDueDate = view.getContextInfo().inpduedate;
  if (!remittanceDueDate) {
    return;
  }
  return {
    _filterExpressions: {
      [GRID_KEY]: {
        expectedDate: { operator: 'lessOrEqual', value: remittanceDueDate }
      }
    }
  };
}

columnDataChange.oldValue:
{
  id: "OB_REM_ProcessPP_Rules",
  compute: (context, util) => {
    const gridKey = "pending payments";

    const selectedRecords = (context._gridSelection && context._gridSelection[gridKey]) 
      ? context._gridSelection[gridKey]._selection 
      : context._selectedRecords || [];

    let totalPay = 0;

    if (selectedRecords) {
      for (let i = 0; i < selectedRecords.length; i++) {
        const rawPayment = selectedRecords[i].realpayment || selectedRecords[i].realPayment || 0;
        const paymentAmount = parseFloat(rawPayment);
        totalPay += isNaN(paymentAmount) ? 0 : paymentAmount;
      }
    }

    const finalValueString = totalPay.toFixed(2);

    return {
      "total count": finalValueString,
      "totalCount": finalValueString,
      "inptotal count": finalValueString
    };
  }
}

columnDataChange.newValue:
async (process, view) => {
  const form = view.theForm;
  const payment = form.getItem('fin_payment_id').getValue();
  const issotrx = form.getItem('issotrx').getValue();
  const trxtype = AP.trxtype(form);

  form._mcShownPrev = false;
  form._mcSyncedOnce = false;

  const caller = view.callerField;
  const parentRecord =
    caller && caller.view && caller.view.callerField && caller.view.callerField.record
      ? caller.view.callerField.record
      : null;
  if (
    parentRecord &&
    typeof parentRecord.affinity !== 'undefined' &&
    typeof parentRecord.matchingType !== 'undefined'
  ) {
    view.theForm.addField({ name: 'bankStatementLineId', value: parentRecord.id });
    view.theForm.hideItem('bankStatementLineId');
  }

  AP.paymentMethodMulticurrency(view, form, !payment);
  AP.reloadLabels(form);

  AP.grid(form, 'glitem').fetchData();
  AP.grid(form, 'credit_to_use').fetchData();

  form.isCreditAllowed =
    form.getItem('received_from').getValue() !== undefined &&
    form.getItem('received_from').getValue() !== null;
  AP.checkSingleActionAvailable(form);

  const overpaymentAction = form.getItem('overpayment_action');
  const map = overpaymentAction.getValueMap() || [];
  const original = {};
  for (const opt of map) {
    original[opt.id || opt.value] = opt.label;
  }
  form._overpaymentOriginalValueMap = original;

  if (issotrx) {
    form.focusInItem('reference_no');
  }
}

async (process, view) => {
  const form = view.theForm;
  const orderInvoiceGrid = AP.grid(form, 'order_invoice');
  const glitemGrid = AP.grid(form, 'glitem');
  const receivedFrom = form.getItem('received_from').getValue();
  const currencyId = form.getItem('c_currency_id').getValue();
  const issotrx = form.getItem('issotrx').getValue();
  const finFinancialAccount = form.getItem('fin_financial_account_id').getValue();
  const amountInvOrds = bd(form.getItem('amount_inv_ords').getValue() || 0);
  const amountGLItem = bd(form.getItem('amount_gl_items').getValue() || 0);
  const total = bd(form.getItem('total').getValue() || 0);
  const actualPayment = bd(form.getItem('actual_payment').getValue() || 0);
  const overpaymentField = form.getItem('overpayment_action');
  const overpaymentAction = overpaymentField.getValue();
  const creditTotalItem = bd(form.getItem('used_credit').getValue() || 0);
  const document = AP.trxtype(form);
  const selectedRecords = orderInvoiceGrid.getSelectedRecords();
  const writeOffLimitPreference = OB.PropertyStore.get('WriteOffLimitPreference', view.windowId);

  let totalWriteOffAmount = ZERO();
  let totalOustandingAmount = ZERO();

  for (const rec of selectedRecords) {
    totalOustandingAmount = totalOustandingAmount.add(bd(rec.outstandingAmount));
  }

  const ordInvRows = (orderInvoiceGrid.data && orderInvoiceGrid.data.localData) ? orderInvoiceGrid.data.localData : [];
  for (let i = 0; i < ordInvRows.length; i++) {
    const editValues = orderInvoiceGrid.getEditValues(i);
    let writeoff = editValues ? editValues.writeoff : undefined;
    if (writeoff === null || writeoff === undefined) {
      writeoff = orderInvoiceGrid.getRecord(i).writeoff;
    }
    if (writeoff) {
      const writeOffLineAmount = bd(orderInvoiceGrid.getRecord(i).outstandingAmount || 0)
        .subtract(bd(orderInvoiceGrid.getEditedRecord(i).amount || 0));
      totalWriteOffAmount = totalWriteOffAmount.add(writeOffLineAmount);
    }
  }

  const fail = (label, title, text) => {
    view.messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, title || null, text || OB.I18N.getLabel(label));
    return { severity: 'error', text: text || OB.I18N.getLabel(label) };
  };

  if (overpaymentAction && receivedFrom === null) {
    return fail('APRM_CreditWithoutBPartner');
  }
  if (total.compareTo(ZERO()) < 0 && creditTotalItem.signum() !== 0) {
    return fail('APRM_CreditWithNegativeAmt');
  }
  if (
    actualPayment.compareTo(total.subtract(creditTotalItem)) > 0 &&
    totalOustandingAmount.compareTo(amountInvOrds.add(totalWriteOffAmount)) > 0
  ) {
    return fail('APRM_JSNOTALLAMOUTALLOCATED');
  }
  if (total.compareTo(actualPayment.add(creditTotalItem)) > 0) {
    return fail('APRM_JSMOREAMOUTALLOCATED');
  }
  if (
    creditTotalItem.compareTo(ZERO()) !== 0 &&
    total.compareTo(creditTotalItem) < 0 &&
    overpaymentField.isVisible && overpaymentField.isVisible() && overpaymentAction === 'CR'
  ) {
    return fail('APRM_MORECREDITAMOUNT');
  }
  if (
    document !== null && document !== '' &&
    (actualPayment.compareTo(ZERO()) === 0 || totalOustandingAmount.compareTo(ZERO()) === 0) &&
    amountGLItem.compareTo(ZERO()) === 0 &&
    view.parentWindow && view.parentWindow.windowId &&
    !overpaymentAction
  ) {
    return fail('APRM_ZEROAMOUNTPAYMENTTRANSACTION');
  }

  const glRows = (glitemGrid.data && glitemGrid.data.allRows) ? glitemGrid.data.allRows : [];
  for (let i = 0; i < glRows.length; i++) {
    const receivedInAmt = bd(glitemGrid.getEditedCell(i, 'received_in') || 0);
    const paidOutAmt = bd(glitemGrid.getEditedCell(i, 'paid_out') || 0);
    if (receivedInAmt.signum() === 0 && paidOutAmt.signum() === 0) {
      return fail('APRM_GLITEMSDIFFERENTZERO');
    }
  }

  const response = await callAction('org.openbravo.advpaymentmngt.actionHandler.AddPaymentOnProcessActionHandler', {
    issotrx,
    receivedFrom,
    currencyId,
    usesCredit: creditTotalItem.compareTo(ZERO()) !== 0,
    generatesCredit: overpaymentField.isVisible && overpaymentField.isVisible() && overpaymentAction === 'CR',
    selectedRecords,
    finFinancialAccount
  });
  const data = response && response.data ? response.data : {};

  if (data.message && data.message.severity === 'error') {
    return fail(null, data.message.title, data.message.text);
  }
  if (writeOffLimitPreference === 'Y' && num(totalWriteOffAmount.toString()) > num(data.writeofflimit)) {
    return fail('APRM_NotAllowWriteOff');
  }

  // All validations passed (client-side + the server pre-submit round-trip).
  // The grid parameters are Window-Reference, so the platform submits the
  // selection itself; returning undefined lets it proceed (do not call
  // view.executeProcess here, which would double-submit).
  return undefined;
}

const ZERO = () => BigDecimal.prototype.ZERO;
const bd = (v) => new BigDecimal(String(v === undefined || v === null || v === '' ? 0 : v));
const isNum = (v) => v !== null && v !== undefined && v !== '' && !Number.isNaN(Number(v));
const num = (v) => Number(v);

const GRID_SETTLE_ID = 'aprmGridSettle';
const GRID_SETTLE_DELAY = 0;

const MC_HANDLER = 'org.openbravo.advpaymentmngt.actionHandler.PaymentMethodMulticurrencyActionHandler';
const DOCNO_HANDLER = 'org.openbravo.advpaymentmngt.actionHandler.AddPaymentDocumentNoActionHandler';
const ORG_HANDLER = 'org.openbravo.advpaymentmngt.actionHandler.AddPaymentOrganizationActionHandler';
const RECEIVEDFROM_HANDLER = 'org.openbravo.advpaymentmngt.actionHandler.ReceivedFromPaymentMethodActionHandler';
const DISPLAYLOGIC_HANDLER = 'org.openbravo.advpaymentmngt.actionHandler.AddPaymentDisplayLogicActionHandler';
const LABELS_HANDLER = 'org.openbravo.advpaymentmngt.actionHandler.AddPaymentReloadLabelsActionHandler';
const ONPROCESS_HANDLER = 'org.openbravo.advpaymentmngt.actionHandler.AddPaymentOnProcessActionHandler';

const AP = {};

AP.trxtype = (form) => (form.getItem('trxtype') ? form.getItem('trxtype').getValue() : '');
AP.grid = (form, param) => form.getItem(param).canvas.viewGrid;

AP.isMultiCurrency = (form) => {
  const fromId = form.getItem('c_currency_id') ? form.getItem('c_currency_id').getValue() : undefined;
  const toId = form.getItem('c_currency_to_id') ? form.getItem('c_currency_to_id').getValue() : undefined;
  return !!fromId && !!toId && fromId !== toId;
};

AP.hasBslAmount = (form) => {
  const item = form.getItem('bslamount');
  if (!item) return false;
  const val = item.getValue();
  if (val === null || val === undefined || val === '') return false;
  return bd(val).compareTo(ZERO()) !== 0;
};

AP.getConvertedAmount = (form, amount, directConversion) => {
  const currencyPrecision = form.getItem('StdPrecision').getValue();
  const exchangeRate = bd(form.getItem('conversion_rate').getValue() || 1);
  if (directConversion) {
    return amount.multiply(exchangeRate).setScale(currencyPrecision, BigDecimal.prototype.ROUND_HALF_UP);
  }
  return amount.divide(exchangeRate, currencyPrecision, BigDecimal.prototype.ROUND_HALF_UP);
};

AP.updateConvertedAmount = (view, form, recalcExchangeRate) => {
  const actualPayment = bd(form.getItem('actual_payment').getValue() || 0);
  const actualConvertedItem = form.getItem('converted_amount');
  const exchangeRateItem = form.getItem('conversion_rate');
  let newConvertedAmount = ZERO();
  let newExchangeRate = BigDecimal.prototype.ONE;
  const exchangeRate = bd(exchangeRateItem.getValue() || 1);
  const actualConverted = bd(actualConvertedItem.getValue() || 0);
  if (!actualConverted || !exchangeRate) return;
  if (recalcExchangeRate) {
    if (actualConverted && actualPayment) {
      if (actualPayment.compareTo(newConvertedAmount) !== 0) {
        newExchangeRate = actualConverted.divide(actualPayment, 15, 2);
        exchangeRateItem.setValue(num(newExchangeRate.toString()));
      }
    } else {
      exchangeRateItem.setValue(num(newExchangeRate.toString()));
    }
  } else if (exchangeRate) {
    newConvertedAmount = AP.getConvertedAmount(form, actualPayment, true);
    exchangeRateItem.setValue(num(exchangeRate.toString()));
    actualConvertedItem.setValue(num(newConvertedAmount.toString()));
  } else {
    actualConvertedItem.setValue(num(actualConverted.toString()));
  }
};

AP.applyBankAmountToConverted = (form) => {
  if (!AP.hasBslAmount(form)) return;
  const bsl = bd(form.getItem('bslamount').getValue() || 0);
  const convItem = form.getItem('converted_amount');
  if (!convItem) return;
  if (bsl.compareTo(ZERO()) === 0) return;
  form._bslApplying = true;
  convItem.setValue(num(bsl.abs().toString()));
  const act = bd(form.getItem('actual_payment').getValue() || 0);
  if (act.compareTo(ZERO()) > 0) {
    AP.updateConvertedAmount(null, form, true);
    form._pendingRecalcRateFromBSL = false;
  } else {
    form._pendingRecalcRateFromBSL = true;
  }
  form._bslApplying = false;
};

AP.syncActualWithExpectedIfMC = (form) => {
  if (!AP.isMultiCurrency(form)) return;
  const expected = num(form.getItem('expected_payment').getValue() || 0);
  form._mcAutoSync = true;
  form.getItem('actual_payment').setValue(expected);
  form._mcAutoSync = false;
  form._mcActualTouched = false;
  if (form.getItem('issotrx').getValue()) {
    AP.distributeAmount(null, form, true);
  }
  AP.updateDifference(form);
  AP.updateConvertedAmount(null, form, false);
  AP.applyBankAmountToConverted(form);
};

AP.recalcDisplayLogicOrReadOnlyLogic = (form, view, affectedParams) => {
  const params = {};
  const thisform = form;
  const thisview = view;
  const creditUseGrid = AP.grid(form, 'credit_to_use');
  params.context = view.getContextInfo();
  delete params.context.order_invoice;
  delete params.context.credit_to_use;
  delete params.context.glitem;

  const callback = (response, data) => {
    if (!data || data.values === null || data.values === undefined) {
      return;
    }
    const values = data.values;
    for (const i in values) {
      if (Object.prototype.hasOwnProperty.call(values, i)) {
        const def = values[i];
        const field = thisform.getItem(i);
        if (field) {
          if (def && typeof def === 'object') {
            if (def.identifier && def.value) {
              field.setValueFromRecord({ id: def.value, _identifier: def.identifier });
            }
          } else {
            field.setValue(def);
          }
        }
      }
    }
    if (thisview && thisview.handleReadOnlyLogic) thisview.handleReadOnlyLogic();
    if (values.credit_to_use_display_logic && values.credit_to_use_display_logic === 'Y') {
      creditUseGrid.fetchData();
    }
    if (thisview && thisview.handleButtonsStatus) thisview.handleButtonsStatus();
  };

  view.fireOnPause('recalcDisplayLogicOrReadOnlyLogic' + affectedParams, () => {
    OB.RemoteCallManager.call(DISPLAYLOGIC_HANDLER, { affectedParams, params }, {}, callback);
  }, 200);
};

AP.reloadLabels = (form) => {
  const params = {
    businessPartner: 'received_from',
    financialAccount: 'fin_financial_account_id',
    issotrx: form.getItem('issotrx').getValue()
  };
  const callback = (response, data) => {
    if (!data || data.values === null || data.values === undefined) {
      return;
    }
    form.getItem('received_from').setTitle(data.values.businessPartner);
    form.getItem('fin_financial_account_id').setTitle(data.values.financialAccount);
  };
  OB.RemoteCallManager.call(LABELS_HANDLER, {}, params, callback);
};

AP.paymentMethodMulticurrency = (view, form, recalcConvRate) => {
  const financialAccountId = form.getItem('fin_financial_account_id').getValue();
  const paymentMethodId = form.getItem('fin_paymentmethod_id').getValue();
  const isSOTrx = form.getItem('issotrx').getValue();
  let currencyId = form.getItem('c_currency_id').getValue();
  const paymentDate = form.getItem('payment_date').getValue();
  const orgId = form.getItem('ad_org_id').getValue();
  const trxtype = AP.trxtype(form);

  if (paymentDate === undefined) {
    view.messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, OB.I18N.getLabel('APRM_PAYMENTDATE_MISSING'));
    return false;
  }

  const callback = (response, data) => {
    if (!data) {
      return;
    }
    let isShown = false;
    if (data.currencyId) {
      form.getItem('c_currency_id').setValueFromRecord({ id: data.currencyId, _identifier: data.currencyIdIdentifier });
    }
    isShown = data.isPayIsMulticurrency && currencyId !== data.currencyToId && currencyId !== undefined;
    if (data.isWrongFinancialAccount && trxtype === '') {
      form.getItem('fin_financial_account_id').setValue('');
    } else if (!data.isWrongFinancialAccount) {
      form.getItem('c_currency_to_id').setValueFromRecord({ id: data.currencyToId, _identifier: data.currencyToIdentifier });
      if (recalcConvRate) {
        form.getItem('conversion_rate').setValue(data.conversionrate);
        form.getItem('converted_amount').setValue(data.convertedamount);
        AP.updateConvertedAmount(view, form, false);
      }
    }
    if (isShown) {
      form.getItem('conversion_rate').show();
      form.getItem('converted_amount').show();
      form.getItem('c_currency_to_id').show();
    } else {
      form.getItem('conversion_rate').hide();
      form.getItem('converted_amount').hide();
      form.getItem('c_currency_to_id').hide();
    }
    const becameVisible = isShown && !form._mcShownPrev;
    if (!isShown) {
      form._mcSyncedOnce = false;
      form._mcPendingSyncMC = false;
    }
    currencyId = form.getItem('c_currency_id').getValue();
    if (becameVisible) {
      form._mcPendingSyncMC = true;
      form._mcSyncedOnce = false;
    }
    form._mcShownPrev = isShown;
  };

  OB.RemoteCallManager.call(MC_HANDLER, {
    paymentMethodId, currencyId, isSOTrx, financialAccountId, paymentDate, orgId
  }, {}, callback);
};

AP.checkSingleActionAvailable = (form) => {
  const documentAction = form.getItem('document_action');
  const options = documentAction.getValueMap();
  if (options && options.length === 1) {
    const opt = options[0];
    documentAction.setValueFromRecord({ id: opt.id || opt.value, _identifier: opt.label });
  } else {
    documentAction.clearValue();
  }
};

AP.updateInvOrderTotal = (form, grid) => {
  let totalAmt = ZERO();
  const selectedRecords = grid.getSelectedRecords();
  const invOrdTotalItem = form.getItem('amount_inv_ords');
  for (const rec of selectedRecords) {
    const amt = grid.getEditedCell(rec, 'amount');
    totalAmt = totalAmt.add(bd(amt));
  }
  invOrdTotalItem.setValue(num(totalAmt.toString()));
  AP.updateTotal(form);
};

AP.updateTotal = (form) => {
  const invOrdTotalItem = form.getItem('amount_inv_ords');
  const glItemsTotalItem = form.getItem('amount_gl_items');
  const totalItem = form.getItem('total');
  let totalAmt = bd(invOrdTotalItem.getValue() || 0);
  totalAmt = totalAmt.add(bd(glItemsTotalItem.getValue() || 0));
  totalItem.setValue(num(totalAmt.toString()));
  AP.updateDifference(form);
};

AP.updateDifference = (form, view) => {
  const total = bd(form.getItem('total').getValue() || 0);
  const actualPayment = bd(form.getItem('actual_payment').getValue() || 0);
  const expectedPayment = bd(form.getItem('expected_payment').getValue() || 0);
  const credit = bd(form.getItem('used_credit').getValue() || 0);
  const differenceItem = form.getItem('difference');
  const expectedDifferenceItem = form.getItem('expectedDifference');
  const totalGLItems = bd(form.getItem('amount_gl_items').getValue() || 0);
  const diffAmt = actualPayment.add(credit).subtract(total);
  const expectedDiffAmt = expectedPayment.add(credit).subtract(total).add(totalGLItems);
  differenceItem.setValue(num(diffAmt.toString()));
  if (expectedDiffAmt.signum() === 0) {
    expectedDifferenceItem.setValue(num(diffAmt.toString()));
  } else {
    expectedDifferenceItem.setValue(num(expectedDiffAmt.toString()));
  }
  if (diffAmt.signum() !== 0) {
    AP.updateDifferenceActions(form);
  }
  if (view) {
    AP.recalcDisplayLogicOrReadOnlyLogic(form, view, ['overpayment_action_display_logic']);
  }
};

AP.updateDifferenceActions = (form) => {
  const issotrx = form.getItem('issotrx').getValue();
  const overpaymentAction = form.getItem('overpayment_action');
  const actualPayment = bd(form.getItem('actual_payment').getValue() || 0);
  const newValueMap = {};
  let defaultValue = '';
  const trxtype = AP.trxtype(form);
  if (trxtype !== '') {
    form.isCreditAllowed = form.getItem('received_from').getValue() !== undefined && form.getItem('received_from').getValue() !== null;
  }
  const original = form._overpaymentOriginalValueMap || {};
  if (form.isCreditAllowed) {
    if (original.CR !== undefined) newValueMap.CR = original.CR;
    if (issotrx || actualPayment.signum() === 0) {
      if (original.RE !== undefined) newValueMap.RE = original.RE;
    } else {
      defaultValue = 'CR';
    }
  }
  overpaymentAction.setValueMap(newValueMap);
  overpaymentAction.setValue(defaultValue);
};

AP.updateActualExpected = (form, view) => {
  const orderInvoice = AP.grid(form, 'order_invoice');
  const issotrx = form.getItem('issotrx').getValue();
  let totalAmountoutstanding = ZERO();
  let totalAmount = ZERO();
  const actualPayment = form.getItem('actual_payment');
  const expectedPayment = form.getItem('expected_payment');
  const generateCredit = bd(form.getItem('generateCredit').getValue() || 0);
  const glitemtotal = bd(form.getItem('amount_gl_items').getValue() || 0);
  const credit = bd(form.getItem('used_credit').getValue() || 0);
  const bslamount = bd(form.getItem('bslamount').getValue() || 0);
  const selectedRecords = orderInvoice.getSelectedRecords();
  for (const rec of selectedRecords) {
    totalAmountoutstanding = totalAmountoutstanding.add(bd(orderInvoice.getEditedCell(rec, 'outstandingAmount')));
    totalAmount = totalAmount.add(bd(orderInvoice.getEditedCell(rec, 'amount')));
  }
  if (selectedRecords.length > 0) {
    expectedPayment.setValue(num(totalAmountoutstanding.toString()));
  } else {
    expectedPayment.setValue(num('0'));
  }
  if (!issotrx) {
    let actpayment = totalAmount.add(glitemtotal).add(generateCredit);
    actualPayment.setValue(num(actpayment.toString()));
    if (credit.compareTo(ZERO()) > 0) {
      if (credit.compareTo(actpayment) > 0) {
        actualPayment.setValue(num('0'));
      } else {
        actualPayment.setValue(num(actpayment.subtract(credit).toString()));
      }
    }
    if (bslamount.compareTo(ZERO()) !== 0) {
      const bslAmountConverted = AP.getConvertedAmount(form, bslamount, false);
      if (actpayment.compareTo(bslAmountConverted.abs()) <= 0) {
        actpayment = bslAmountConverted.abs();
        actualPayment.setValue(num(actpayment.toString()));
      }
    }
    AP.updateDifference(form, view);
    AP.updateConvertedAmount(null, form, false);
  }
  if (form._mcSyncInProgress) {
    // no-op while a multicurrency sync is already running
  } else if (form._mcPendingSyncMC && AP.isMultiCurrency(form)) {
    const expNow = num(form.getItem('expected_payment').getValue() || 0);
    const actNow = num(form.getItem('actual_payment').getValue() || 0);
    if (expNow > 0 && (actNow === 0 || !form._mcActualTouched)) {
      form._mcPendingSyncMC = false;
      form._mcSyncInProgress = true;
      AP.syncActualWithExpectedIfMC(form);
      form._mcSyncInProgress = false;
      form._mcSyncedOnce = true;
    }
  }
  AP.applyBankAmountToConverted(form);
};

AP.updateGLItemsTotal = (form, view, rowNum, remove) => {
  let totalAmt = ZERO();
  const grid = AP.grid(form, 'glitem');
  const glItemTotalItem = form.getItem('amount_gl_items');
  const issotrx = form.getItem('issotrx').getValue();
  const allRows = (grid.data && grid.data.allRows) ? grid.data.allRows : [];
  const allRecords = allRows.length;
  for (let i = 0; i < allRecords; i++) {
    if (remove && i === rowNum) continue;
    const receivedInAmt = bd(grid.getEditedCell(i, 'received_in') || 0);
    const paidOutAmt = bd(grid.getEditedCell(i, 'paid_out') || 0);
    if (issotrx) {
      totalAmt = totalAmt.add(receivedInAmt).subtract(paidOutAmt);
    } else {
      totalAmt = totalAmt.subtract(receivedInAmt).add(paidOutAmt);
    }
  }
  if (allRecords === 0) totalAmt = ZERO();
  glItemTotalItem.setValue(num(totalAmt.toString()));
  AP.updateTotal(form);
  if (view) {
    AP.recalcDisplayLogicOrReadOnlyLogic(form, view, ['overpayment_action_display_logic']);
  }
  return true;
};

AP.updateCreditTotal = (form) => {
  let totalAmt = ZERO();
  const grid = AP.grid(form, 'credit_to_use');
  const selectedRecords = grid.getSelectedRecords();
  const creditTotalItem = form.getItem('used_credit');
  for (const rec of selectedRecords) {
    totalAmt = totalAmt.add(bd(grid.getEditedCell(rec, 'paymentAmount')));
  }
  creditTotalItem.setValue(num(totalAmt.toString()));
  AP.updateTotal(form);
  return true;
};

AP.distributeAmount = (view, form, onActualPaymentChange) => {
  let amount = bd(form.getItem('actual_payment').getValue() || 0);
  const orderInvoice = AP.grid(form, 'order_invoice');
  const issotrx = form.getItem('issotrx').getValue();
  const payment = form.getItem('fin_payment_id').getValue();
  let negativeamt = ZERO();
  let differenceamt = ZERO();
  const creditamt = bd(form.getItem('used_credit').getValue() || 0);
  const glitemamt = bd(form.getItem('amount_gl_items').getValue() || 0);
  const orderInvoiceData = (orderInvoice.data && orderInvoice.data.localData) ? orderInvoice.data.localData : [];
  const total = orderInvoiceData.length;
  const autoDistributeAmt = OB.PropertyStore.get('APRM_AutoDistributeAmt');

  if (autoDistributeAmt !== 'N' && autoDistributeAmt !== '"N"') {
    amount = amount.subtract(glitemamt);
    amount = amount.add(creditamt);
    if (issotrx && AP.isMultiCurrency(form)) {
      if (amount.compareTo(ZERO()) === 0) {
        const exp = bd(form.getItem('expected_payment').getValue() || 0);
        if (exp.compareTo(ZERO()) > 0) amount = exp;
      }
    }
    for (let i = 0; i < total; i++) {
      const row = orderInvoiceData[i];
      if (row && typeof row === 'object' && Object.keys(row).length > 0) {
        const outstandingAmount = bd(row.outstandingAmount);
        if (outstandingAmount.signum() < 0) {
          negativeamt = negativeamt.add(outstandingAmount.abs());
        }
      }
    }
    if (amount.compareTo(negativeamt.negate()) > 0 && (onActualPaymentChange || payment)) {
      amount = amount.add(negativeamt);
    }
    for (let i = 0; i < total; i++) {
      const row = orderInvoiceData[i];
      if (!row || typeof row !== 'object' || Object.keys(row).length === 0) continue;
      const editValues = orderInvoice.getEditValues(i);
      let writeoff = editValues ? editValues.writeoff : undefined;
      let amt = bd((editValues ? editValues.amount : 0) || 0);
      if (writeoff === null || writeoff === undefined) {
        writeoff = orderInvoice.getRecord(i).writeoff;
        amt = bd(orderInvoice.getRecord(i).amount || 0);
      }
      if (writeoff && issotrx) {
        amount = amount.subtract(amt);
        continue;
      }
      let outstandingAmount = bd(orderInvoice.getRecord(i).outstandingAmount);
      if (payment && !onActualPaymentChange && orderInvoice.getRecord(i).obSelected) {
        outstandingAmount = bd(orderInvoice.getRecord(i).amount);
      } else if (outstandingAmount.signum() < 0 && amount.signum() < 0) {
        if (outstandingAmount.abs().compareTo(amount.abs()) > 0) {
          differenceamt = outstandingAmount.subtract(amount);
          outstandingAmount = amount;
          amount = amount.subtract(differenceamt);
        }
      } else if (outstandingAmount.signum() > -1 && amount.signum() > -1 && outstandingAmount.compareTo(amount) > 0) {
        outstandingAmount = amount;
      }
      if (amount.signum() === 0) {
        if (outstandingAmount.signum() < 0 && (onActualPaymentChange || payment)) {
          orderInvoice.setEditValue(i, 'amount', num(outstandingAmount.toString()));
          orderInvoice.selectRecord(i);
        } else {
          orderInvoice.deselectRecord(i);
          orderInvoice.setEditValue(i, 'amount', num('0'));
        }
      } else if (amount.signum() === 1) {
        orderInvoice.setEditValue(i, 'amount', num(outstandingAmount.toString()));
        orderInvoice.selectRecord(i);
        if (outstandingAmount.signum() >= 0 || amount.signum() <= 0) {
          amount = amount.subtract(outstandingAmount);
        }
      } else if (outstandingAmount.signum() < 0) {
        orderInvoice.setEditValue(i, 'amount', num(outstandingAmount.toString()));
        orderInvoice.selectRecord(i);
        if (outstandingAmount.signum() <= 0 || amount.signum() <= 0) {
          amount = amount.subtract(outstandingAmount);
        }
      } else {
        orderInvoice.deselectRecord(i);
        orderInvoice.setEditValue(i, 'amount', num('0'));
      }
    }
    AP.updateActualExpected(form, view);
  }
  AP.updateInvOrderTotal(form, orderInvoice);
};

AP.doSelectionChanged = (record, state, view) => {
  const form = view.theForm;
  const orderInvoice = AP.grid(form, 'order_invoice');
  let amount = bd(form.getItem('actual_payment').getValue() || 0);
  const distributedAmount = bd(form.getItem('amount_inv_ords').getValue() || 0);
  const issotrx = form.getItem('issotrx').getValue();
  let outstandingAmount = bd(record.outstandingAmount);
  const glitem = bd(form.getItem('amount_gl_items').getValue() || 0);
  const credit = bd(form.getItem('used_credit').getValue() || 0);
  const bslamount = bd(form.getItem('bslamount').getValue() || 0);

  // Exclude this row's own already-distributed amount from the pool so a re-fire of
  // selectionChanged on an already-assigned row stays idempotent (otherwise the row's
  // own amount, folded into amount_inv_ords, is subtracted from its own pool and the row
  // collapses to the leftover/overpayment).
  const ownCurrent = bd(orderInvoice.getEditedCell(record, 'amount') || 0);
  amount = amount.subtract(distributedAmount.subtract(ownCurrent)).subtract(glitem).add(credit);

  if (issotrx) {
    if (amount.signum() !== 0 && state) {
      if (outstandingAmount.signum() < 0 && amount.signum() < 0) {
        if (outstandingAmount.abs().compareTo(amount.abs()) > 0) outstandingAmount = amount;
      } else if (outstandingAmount.compareTo(amount) > 0) {
        outstandingAmount = amount;
      }
      orderInvoice.setEditValue(orderInvoice.getRecordIndex(record), 'amount', num(outstandingAmount.toString()));
    }
  } else if (state) {
    if (bslamount.compareTo(ZERO()) !== 0) {
      if (outstandingAmount.compareTo(amount) > 0) {
        orderInvoice.setEditValue(orderInvoice.getRecordIndex(record), 'amount', num(amount.toString()));
      } else {
        orderInvoice.setEditValue(orderInvoice.getRecordIndex(record), 'amount', num(outstandingAmount.toString()));
      }
    } else {
      orderInvoice.setEditValue(orderInvoice.getRecordIndex(record), 'amount', num(outstandingAmount.toString()));
    }
  }
  AP.updateInvOrderTotal(form, orderInvoice);
  AP.updateActualExpected(form, view);
  AP.updateDifference(form, view);
  AP.applyBankAmountToConverted(form);
};

AP.doSelectionChangedCredit = (record, state, view) => {
  const form = view.theForm;
  const issotrx = form.getItem('issotrx').getValue();
  const grid = AP.grid(form, 'credit_to_use');
  const outstanding = bd(record.outstandingAmount);
  if (state) {
    grid.setEditValue(grid.getRecordIndex(record), 'paymentAmount', num(outstanding.toString()));
  } else {
    grid.setEditValue(grid.getRecordIndex(record), 'paymentAmount', num('0'));
  }
  AP.updateCreditTotal(form);
  AP.updateActualExpected(form, view);
  if (issotrx) {
    AP.distributeAmount(view, form, true);
  }
};

// Defers `fn` until after the freshly delivered grid rows have committed to the
// grid controller's read store. At onGridLoad firing time the controller-backed
// reads/writes (getRecord/getSelectedRecords/setEditValue) still see the pre-fetch
// rows, so any settling that reads or writes edited cells must run on the next
// tick. This mirrors the classic ordInvDataArrived deferral (isc.Timer.setTimeout).
AP.afterGridSettle = (grid, paramName, fn) => {
  if (grid && grid.fireOnPause) {
    grid.fireOnPause(GRID_SETTLE_ID + ':' + paramName, fn, GRID_SETTLE_DELAY);
  } else {
    fn();
  }
};

// Mirrors classic ordInvDataArrived: for each backend pre-selected order/invoice row
// (read from grid.getSelectedRecords() AFTER the deferral — classic also reads
// getSelectedRecords() after dataArrived), keep/seed its editable `amount` (its own
// amount, falling back to the outstanding) and re-assert selection, then refresh the
// invoice/order total.
AP.seedPreselectedOrderInvoice = (form, grid, selectedRecords) => {
  const selected = selectedRecords || (grid.getSelectedRecords ? grid.getSelectedRecords() : []);
  for (let i = 0; i < selected.length; i++) {
    const record = selected[i];
    if (!record || typeof record !== 'object') continue;
    const idx = grid.getRecordIndex(record);
    const ownAmount = bd(record.amount || 0);
    const outstanding = bd(record.outstandingAmount || 0);
    const amount = ownAmount.compareTo(ZERO()) !== 0 ? ownAmount : outstanding;
    grid.setEditValue(idx, 'amount', num(amount.toString()));
    grid.selectRecord(idx);
  }
  AP.updateInvOrderTotal(form, grid);
};

// Mirrors classic selectionChangedCredit for backend pre-selected credit rows: seed
// each selected credit's editable paymentAmount from its outstanding amount (classic
// creditOnLoadGrid leaves seeding to selectionChanged, which never fires for rows the
// datasource delivers already selected → new-#8).
AP.seedPreselectedCredit = (form, grid, selectedRecords) => {
  const selected = selectedRecords || (grid.getSelectedRecords ? grid.getSelectedRecords() : []);
  for (let i = 0; i < selected.length; i++) {
    const record = selected[i];
    if (!record || typeof record !== 'object') continue;
    const idx = grid.getRecordIndex(record);
    const outstanding = bd(record.outstandingAmount || 0);
    grid.setEditValue(idx, 'paymentAmount', num(outstanding.toString()));
  }
};

AP.orderInvoiceGridValidation = (item, validator, value, record) => {
  const view = item.grid ? item.grid.view : null;
  const messageBar = view ? view.messageBar : null;
  const outstanding = bd(record.outstandingAmount);
  const paidamount = bd(record.amount);
  if (!isNum(record.amount)) {
    if (messageBar) messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, OB.I18N.getLabel('APRM_NotValidNumber'));
    return false;
  }
  if (outstanding.abs().compareTo(paidamount.abs()) < 0) {
    if (messageBar) messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, OB.I18N.getLabel('APRM_MoreAmountThanOutstanding'));
    return false;
  }
  if (paidamount.signum() === 0 && record.writeoff === false) {
    if (messageBar) messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, OB.I18N.getLabel('APRM_JSZEROUNDERPAYMENT'));
    return false;
  }
  if ((paidamount.signum() < 0 && outstanding.signum() > 0) || (paidamount.signum() > 0 && outstanding.signum() < 0)) {
    if (messageBar) messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, OB.I18N.getLabel('APRM_ValueOutOfRange'));
    return false;
  }
  return true;
};

AP.creditValidation = (item, validator, value, record) => {
  const view = item.grid ? item.grid.view : null;
  const messageBar = view ? view.messageBar : null;
  const outstanding = bd(record.outstandingAmount);
  const paidamount = bd(record.paymentAmount);
  if (!isNum(record.paymentAmount)) {
    if (messageBar) messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, OB.I18N.getLabel('APRM_NotValidNumber'));
    return false;
  }
  if (outstanding.abs().compareTo(paidamount.abs()) < 0) {
    if (messageBar) messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, OB.I18N.getLabel('APRM_MoreAmountThanOutstanding'));
    return false;
  }
  if (paidamount.signum() === 0) {
    if (messageBar) messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, OB.I18N.getLabel('aprm_biggerthanzero'));
    return false;
  }
  return true;
};

AP.glItemAmountOnChange = (item, view, form, grid) => {
  const receivedInAmt = bd(grid.getEditedCell(item.rowNum, 'received_in') || 0);
  const paidOutAmt = bd(grid.getEditedCell(item.rowNum, 'paid_out') || 0);
  if (item.columnName === 'received_in' && receivedInAmt.signum() !== 0) {
    grid.setEditValue(item.rowNum, 'paidOut', num('0'));
  } else if (item.columnName === 'paid_out' && paidOutAmt.signum() !== 0) {
    grid.setEditValue(item.rowNum, 'receivedIn', num('0'));
  }
  AP.updateGLItemsTotal(form, view, item.rowNum, false);
  AP.updateActualExpected(form, view);
  AP.updateDifference(form, view);
  return true;
};

AP.orderInvoiceAmountOnChange = (item, view, form, grid) => {
  AP.updateActualExpected(form, view);
  AP.updateInvOrderTotal(form, grid);
};

AP.updateCreditOnChange = (item, view, form, grid) => {
  const issotrx = form.getItem('issotrx').getValue();
  AP.updateCreditTotal(form);
  if (issotrx) {
    AP.distributeAmount(view, form, true);
  }
  AP.updateDifference(form, view);
  AP.updateActualExpected(form, view);
  return true;
};

AP.refetchOrderInvoiceGrid = (form) => {
  const ordinvgrid = AP.grid(form, 'order_invoice');
  ordinvgrid.invalidateCache();
};

AP.registerGridHooks = (grid, paramName, view) => {
  if (paramName === 'order_invoice') {
    grid.onSelectionToggle((record, state) => AP.doSelectionChanged(record, state, view));
    grid.setColumnOnChange('amount', (item, v, form, g) => AP.orderInvoiceAmountOnChange(item, view, form, g));
    grid.setColumnValidator('amount', (item, validator, value, record) => AP.orderInvoiceGridValidation(item, validator, value, record));
  } else if (paramName === 'glitem') {
    grid.setColumnOnChange('received_in', (item, v, form, g) => AP.glItemAmountOnChange(item, view, form, g));
    grid.setColumnOnChange('paid_out', (item, v, form, g) => AP.glItemAmountOnChange(item, view, form, g));
  } else if (paramName === 'credit_to_use') {
    grid.onSelectionToggle((record, state) => AP.doSelectionChangedCredit(record, state, view));
    grid.setColumnOnChange('paymentAmount', (item, v, form, g) => AP.updateCreditOnChange(item, view, form, g));
    grid.setColumnValidator('paymentAmount', (item, validator, value, record) => AP.creditValidation(item, validator, value, record));
  }
};

OB.APRM = OB.APRM || {};
OB.APRM.AddPayment = AP;

return { AP, bd, num, isNum, ZERO, GRID_SETTLE_ID, GRID_SETTLE_DELAY };

async (process, view) => {
  const AMOUNT_NOT_EQUALS = 'OBFBPS_Err_AmountNotEquals';
  const SELECT_INVOICE = 'OBFBPS_Err_SelectInvoice';
  const purchaseInvoiceGrid = getInvoiceGrid(view, PURCHASE_INVOICE);
  const salesInvoiceGrid = getInvoiceGrid(view, SALES_INVOICE);
  const amountPurchase = getSelectedAmount(purchaseInvoiceGrid);
  const amountSales = getSelectedAmount(salesInvoiceGrid);
  view.theForm.getItem(PURCHASE_AMOUNT).setValue(amountPurchase);
  view.theForm.getItem(SALES_AMOUNT).setValue(amountSales);
  const exceedInvoice = checkAmounts(view, purchaseInvoiceGrid, salesInvoiceGrid);
  if (exceedInvoice) {
    return { severity: 'error', text: OB.I18N.getLabel(AMOUNT_EXCEED_PENDING, [exceedInvoice]) };
  }
  if (amountPurchase !== amountSales) {
    const text = OB.I18N.getLabel(AMOUNT_NOT_EQUALS);
    view.messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, text);
    return { severity: 'error', text };
  }
  if (amountPurchase === 0) {
    const text = OB.I18N.getLabel(SELECT_INVOICE);
    view.messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, text);
    return { severity: 'error', text };
  }
  return undefined;
}

const PURCHASE_INVOICE = 'OBFBPS_PurchaseInvoice';
const SALES_INVOICE = 'OBFBPS_SalesInvoice';
const PURCHASE_AMOUNT = 'OBFBPS_PurchaseAmount';
const SALES_AMOUNT = 'OBFBPS_SalesAmount';
const PEND_AMOUNT = 'OBFBPS_PendAmount';
const AMOUNT_EXCEED_PENDING = 'OBFBPS_Err_AmountExceedPending';
const SETTLEMENT_AMOUNT = 'settlementAmount';

const getInvoiceGrid = (view, paramName) => view.theForm.getItem(paramName).canvas.viewGrid;

const getSelectedAmount = grid => {
  let amount = BigDecimal.prototype.ZERO;
  const records = grid.getSelectedRecords();
  records.forEach(record => {
    const index = grid.getRecordIndex(record);
    const item = grid.getEditValues(index);
    const editedAmount = item && item[SETTLEMENT_AMOUNT];
    const value = editedAmount ? editedAmount : record[SETTLEMENT_AMOUNT] || 0;
    amount = amount.add(new BigDecimal(String(value)));
  });
  return Number(amount.toString());
};

const checkInvoiceAmount = grid => {
  let result = null;
  const records = grid.getSelectedRecords();
  records.every(record => {
    const index = grid.getRecordIndex(record);
    const item = grid.getEditValues(index);
    const editedAmount = item && item[SETTLEMENT_AMOUNT];
    if (editedAmount && editedAmount > record.amount) {
      result = record.documentNo;
      return false;
    }
    return true;
  });
  return result;
};

const checkAmounts = (view, purchaseInvoiceGrid, salesInvoiceGrid) => {
  view.messageBar.hide();
  const grids = [purchaseInvoiceGrid, salesInvoiceGrid];
  for (let i = 0; i < grids.length; i++) {
    const invoice = checkInvoiceAmount(grids[i]);
    if (invoice) {
      const text = OB.I18N.getLabel(AMOUNT_EXCEED_PENDING, [invoice]);
      view.messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, text);
      return invoice;
    }
  }
  return null;
};

const setAmounts = view => {
  const purchaseInvoiceGrid = getInvoiceGrid(view, PURCHASE_INVOICE);
  const salesInvoiceGrid = getInvoiceGrid(view, SALES_INVOICE);
  const amountPurchase = getSelectedAmount(purchaseInvoiceGrid);
  const amountSales = getSelectedAmount(salesInvoiceGrid);
  view.theForm.getItem(PURCHASE_AMOUNT).setValue(amountPurchase);
  view.theForm.getItem(SALES_AMOUNT).setValue(amountSales);
  view.theForm.getItem(PEND_AMOUNT).setValue(amountSales - amountPurchase);
};

// Live selection-toggle recompute. The module body runs once per modal open, so
// recomputeAmounts is a single stable reference; passing that same reference to
// every grid's grid.onSelectionToggle lets the substrate's reference-dedup
// collapse repeated registrations across grid reloads. It reads the latest view
// captured on grid load, so it always recomputes against a current view proxy.
let lastView = null;
const setLastView = view => { lastView = view; };
const recomputeAmounts = () => { if (lastView) setAmounts(lastView); };

// Live recompute when the user edits a row's Settlement Amount cell. Ported
// 1:1 from classic amountChange(item, view, form, grid): recompute every total
// (setAmounts) and revalidate the over-pending banner (checkAmounts), ignoring
// the return value exactly as classic did. Registered via grid.setColumnOnChange
// under SETTLEMENT_AMOUNT, so it is one stable module-scope reference reused by
// both grids' on_grid_load (re-registration is idempotent by column key).
const onSettlementAmountChange = (item, view, form, grid) => {
  setAmounts(view);
  const purchaseInvoiceGrid = getInvoiceGrid(view, PURCHASE_INVOICE);
  const salesInvoiceGrid = getInvoiceGrid(view, SALES_INVOICE);
  checkAmounts(view, purchaseInvoiceGrid, salesInvoiceGrid);
};

return {
  PURCHASE_INVOICE,
  SALES_INVOICE,
  PURCHASE_AMOUNT,
  SALES_AMOUNT,
  AMOUNT_EXCEED_PENDING,
  SETTLEMENT_AMOUNT,
  getInvoiceGrid,
  getSelectedAmount,
  checkInvoiceAmount,
  checkAmounts,
  setAmounts,
  setLastView,
  recomputeAmounts,
  onSettlementAmountChange
};

async (process, view) => {
  const records = view.hookData.selectedRecords ?? [];
  if (records.length === 0) {
    return { error: { msgText: OB.I18N.getLabel("OBUIAPP_NoSelectedRecords"), msgType: "error" } };
  }
  return await runSiiAction(records);
}

// @module-scope
// Shared helper mirroring the classic OB.AEATSII.execute (ModDefinicionProceso.js:14):
// one remote call, the server's own severity/title/text in the banner, then a grid
// refresh. Cloned per process because payscript module scope is per-process.
const ACTION_HANDLER = "org.openbravo.module.sii.process.MultiCashReceiptSIIModification";
const WARNING_LABEL = "AEATSII_WARNING_SEND";
const TITLE_LABEL = "AEATSII_TITLE_SEND";

const runSiiAction = async (records) => {
  const confirmed = await confirm(OB.I18N.getLabel(WARNING_LABEL), {
    title: OB.I18N.getLabel(TITLE_LABEL),
  });
  // Classic closes the popup and runs nothing when the user declines.
  if (!confirmed) return { type: "closeModal" };

  const response = await callAction(ACTION_HANDLER, {
    ids: records.map((record) => record.id),
    orgid: records[0].organization,
  });

  const message = response?.data?.message ?? {};
  return {
    message: { msgType: message.severity, msgTitle: message.title, msgText: message.text },
    responseActions: [{ refreshGrid: {} }],
  };
};

return { runSiiAction };

const UOM_MANAGEMENT = 'UomManagement';
const RETURNABLE_HANDLER =
  'org.openbravo.common.actionhandler.ServiceReturnableActionHandler';
const LABEL_OUT_OF_RANGE = 'OBUIAPP_RM_OutOfRange';
const LABEL_OUT_OF_RANGE_AUM = 'OBUIAPP_RM_OutOfRange_AUM';

const ZERO = () => BigDecimal.prototype.ZERO;
const ONE = () => BigDecimal.prototype.ONE;
const bd = (value) => new BigDecimal(String(value));

// Faithful reproduction of the classic SmartClient `isc.isA.Number(x)` type-check,
// which the new-UI `isc` shim does not expose. Pure, self-contained, no platform dependency.
const isNum = (value) => typeof value === 'number' && isFinite(value);

const isUomManagementEnabled = () =>
  OB.PropertyStore.get(UOM_MANAGEMENT) === 'Y';

const appliesUom = (record) =>
  isUomManagementEnabled() && record.returnedUOM !== record.uOM;

const showOutOfRange = (view, record, remaining, newReturnedQty) => {
  if (appliesUom(record)) {
    view.messageBar.setMessage(
      isc.OBMessageBar.TYPE_ERROR,
      null,
      OB.I18N.getLabel(LABEL_OUT_OF_RANGE_AUM, [
        newReturnedQty.toString(),
        record.uOM$_identifier,
        remaining.toString()
      ])
    );
  } else {
    view.messageBar.setMessage(
      isc.OBMessageBar.TYPE_ERROR,
      null,
      OB.I18N.getLabel(LABEL_OUT_OF_RANGE, [remaining.toString()])
    );
  }
};

const returnedUomValidate = (item, validator, value, record) => {
  const view = item.grid.view;
  const movementQty = isNum(record.movementQuantity)
    ? bd(record.movementQuantity)
    : ZERO();
  const returnedQty = isNum(record.returnQtyOtherRM)
    ? bd(record.returnQtyOtherRM)
    : ZERO();
  let newReturnedQty = isNum(record.returned) ? bd(record.returned) : ZERO();

  if (appliesUom(record)) {
    newReturnedQty = newReturnedQty.multiply(
      isNum(record.aumConversionRate) ? bd(record.aumConversionRate) : ONE()
    );
  }

  const remaining = movementQty.subtract(returnedQty);
  if (newReturnedQty.compareTo(remaining) <= 0 && record.returned > 0) {
    view.messageBar.hide(true);
    return true;
  }
  showOutOfRange(view, record, remaining, newReturnedQty);
  return false;
};

const orderQtyValidate = (item, validator, value, record) => {
  const view = item.grid.view;
  if (!isNum(value)) {
    return false;
  }
  if (record.goodsShipmentLine === null || record.goodsShipmentLine === '') {
    return value !== null && value > 0;
  }
  const movementQty =
    record.movementQuantity !== null ? bd(record.movementQuantity) : ZERO();
  const returnedQty =
    record.returnQtyOtherRM !== null ? bd(record.returnQtyOtherRM) : ZERO();
  let newReturnedQty = bd(value);

  if (appliesUom(record)) {
    newReturnedQty = newReturnedQty.multiply(bd(record.aumConversionRate));
  }

  const remaining = movementQty.subtract(returnedQty);
  if (value !== null && newReturnedQty.compareTo(remaining) <= 0 && value > 0) {
    view.messageBar.hide(true);
    return true;
  }
  showOutOfRange(view, record, remaining, newReturnedQty);
  return false;
};

const orderSelectionChange = (grid, view, record, state) => {
  if (!state) {
    return;
  }
  let contextInfo = view.parentWindow.activeView.getContextInfo(
    false,
    true,
    true,
    true
  );
  if (!contextInfo.inpdateordered) {
    contextInfo = view.parentWindow.activeView.parentView.getContextInfo(
      false,
      true,
      true,
      true
    );
  }
  if (!record.returnReason) {
    record.returnReason = contextInfo.inpcReturnReasonId;
  }
  OB.RemoteCallManager.call(
    RETURNABLE_HANDLER,
    {
      rfcOrderDate: contextInfo.inpdateordered,
      goodsShipmentId: record.id,
      productId: record.product
    },
    {},
    (response, data) => {
      if (!data.message) {
        return;
      }
      if (data.message.severity === isc.OBMessageBar.TYPE_ERROR) {
        view.messageBar.setMessage(
          isc.OBMessageBar.TYPE_ERROR,
          data.message.title,
          data.message.text
        );
        grid.deselectRecord(grid.getRecordIndex(record));
      } else {
        view.messageBar.setMessage(
          isc.OBMessageBar.TYPE_WARNING,
          data.message.title,
          data.message.text
        );
      }
    }
  );
};

return {
  returnedUomValidate,
  orderQtyValidate,
  orderSelectionChange
};

async (process, view) => {
  const TABLE_ID = "318";
  const HANDLER = "com.smf.jobs.defaults.ProcessInvoicesDefaults";
  const form = view.theForm;
  const docActionField = form.getItem("DocAction");
  const selectedRecords = view.selectedRecords || [];
  const isProcessing = "";

  const documentStatuses = [];
  const documentActions = [];
  for (const record of selectedRecords) {
    if (!documentStatuses.includes(record.documentStatus)) {
      documentStatuses.push(record.documentStatus);
    }
    if (!documentActions.includes(record.documentAction)) {
      documentActions.push(record.documentAction);
    }
  }

  form.getItem("VoidDate").hide();
  form.getItem("VoidAccountingDate").hide();
  form.getItem("POReference").hide();

  OB.RemoteCallManager.call(
    HANDLER,
    {
      documentStatuses: documentStatuses,
      isProcessing: isProcessing,
      tableId: TABLE_ID,
    },
    {},
    (response, data, request) => {
      const actions = data.actions || [];
      const currentValues = docActionField.getValueMap();
      const newValues = [];

      for (const action of actions) {
        const match = currentValues.find((o) => o.value === action || o.id === action);
        if (match) {
          newValues.push(match);
        }
      }

      docActionField.setValueMap(newValues);

      const firstAction = documentActions[0];
      const hasFirstAction = newValues.some((o) => o.value === firstAction || o.id === firstAction);
      if (hasFirstAction) {
        docActionField.setValueProgrammatically(firstAction);
      } else {
        docActionField.setValueProgrammatically(docActionField.getFirstOptionValue());
      }
    }
  );
}

async (process, view) => {
  const recordIds = view.hookData.recordIds ?? [];
  if (recordIds.length === 0) {
    return { error: { msgText: OB.I18N.getLabel("OBUIAPP_NoSelectedRecords"), msgType: "error" } };
  }
  return await runOpenClose(recordIds);
}

// @module-scope
// Mirrors OB.OpenClose.execute + isc.OpenClosePeriodProcessPopup
// (periodControlStatus.js:95 and :130): fetch the action combo, ask the user,
// post the choice, report, refresh.
const ACTION_HANDLER = "org.openbravo.client.application.event.OpenClosePeriodHandler";
const ACTION_FIELD = "action";

// SmartClient value maps are { value: label } objects; a LIST field takes
// [{ value, label }]. Tolerates the array form in case the handler changes.
const toRefList = (valueMap) => {
  if (Array.isArray(valueMap)) return valueMap;
  return Object.entries(valueMap ?? {}).map(([value, label]) => ({ value, label: String(label) }));
};

const runOpenClose = async (recordIds) => {
  const combo = await callAction(ACTION_HANDLER, { recordIdList: recordIds, action: "ACTION_COMBO" });
  const data = combo?.data;
  if (!data) {
    return { error: { msgText: OB.I18N.getLabel("OBUIAPP_ErrorInProcess"), msgType: "error" } };
  }

  const refList = toRefList(data.actionComboBox?.valueMap);
  // Classic sets defaultToFirstOption on the field, so an absent default still
  // arrives at the dialog preselected.
  const defaultValue = data.actionComboBox?.defaultValue ?? refList[0]?.value;

  const collected = await openDynamicForm({
    title: "Process Request",
    fields: [
      {
        name: ACTION_FIELD,
        inputType: "LIST",
        refList,
        defaultValue,
      },
    ],
  });
  // Cancel: classic closes the popup and posts nothing.
  if (!collected) return { type: "closeModal" };

  const response = await callAction(ACTION_HANDLER, {
    closePeriodStepId: data.nextStepId,
    recordIdList: recordIds,
    action: collected[0]?.value,
  });

  const message = response?.data?.message ?? {};
  return {
    message: { msgType: message.severity, msgText: message.text },
    responseActions: [{ refreshGrid: {} }],
  };
};

return { runOpenClose };

async (process, view) => {
  view.messageBar.setMessage(
    isc.OBMessageBar.TYPE_INFO,
    null,
    OB.I18N.getLabel('CreateFromMatchPOQtys')
  );
}

async (process, view) => {
  const GL_ITEM_PARAM = 'c_glitem_id';
  const HANDLER = 'org.openbravo.common.actionhandler.CheckAvailableCreditActionHandler';
  const form = view.theForm;
  const context = view.parentWindow.view.getContextInfo();
  const businessPartnerId = context.C_BPartner_ID || context.inpcBpartnerId;
  // The Currency parameter defaults to the BP currency (@BP_Currency_ID@). Its form value may
  // not be synced yet when onLoad runs, so fall back to the launching record's currency from the
  // context (keyed by inputName, e.g. inpbpCurrencyId — the same key onProcess reads). `null`
  // (not undefined) keeps the key in the JSON payload; the handler treats null/empty as
  // availableCredit:false. Classic always sends the key.
  const currencyId = form.getItem('C_Currency_ID').getValue() || context.inpbpCurrencyId || null;
  const glItem = form.getItem(GL_ITEM_PARAM);

  const callback = (response, data) => {
    if (data.availableCredit) {
      view.messageBar.setMessage(isc.OBMessageBar.TYPE_WARNING, null, OB.I18N.getLabel('BPCurrencyChange'));
      glItem.show();
      glItem.setRequired(true);
    } else {
      glItem.hide();
    }
    form.redraw();
    view.handleButtonsStatus();
  };

  OB.RemoteCallManager.call(HANDLER, {
    businessPartnerId: businessPartnerId,
    currencyId: currencyId
  }, {}, callback);
}

async (process, view) => {
  const form = view.theForm;
  const context = view.parentWindow.view.getContextInfo();
  const currencyFromId = context.inpbpCurrencyId;
  const currencyToId = form.getItem('C_Currency_ID').getValue();
  const glItemId = form.getItem('c_glitem_id').getValue();
  const setAmount = form.getItem('Amount').getValue();
  const currentBalance = context.inpsoCreditused;
  const foreignAmount = form.getItem('Foreign_Amount').getValue();

  if (currencyFromId !== currencyToId && glItemId && setAmount === true && currentBalance === 0 && foreignAmount !== 0) {
    const text = OB.I18N.getLabel('BPCurrencyChangeRate');
    view.messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, text);
    return { severity: 'error', text };
  }

  const response = await view.executeProcess();
  return response && response.message;
}

async (process, view) => {
  const records = view.hookData.selectedRecords ?? [];
  if (records.length === 0) {
    return { error: { msgText: OB.I18N.getLabel("OBUIAPP_NoSelectedRecords"), msgType: "error" } };
  }
  return await runSiiAction(records);
}

// @module-scope
// Shared helper mirroring the classic OB.AEATSII.execute (ModDefinicionProceso.js:14):
// one remote call, the server's own severity/title/text in the banner, then a grid
// refresh. Cloned per process because payscript module scope is per-process.
const ACTION_HANDLER = "org.openbravo.module.sii.process.MultiInvoiceSIIModification";
const WARNING_LABEL = "AEATSII_WARNING_SEND";
const TITLE_LABEL = "AEATSII_TITLE_SEND";

const runSiiAction = async (records) => {
