(item, view, form, grid) => {
  const TYPE_DEPOSIT = 'BPD';
  const TYPE_WITHDRAWAL = 'BPW';
  const value = item.getValue();
  const depositamt = form.getItem('depositamt');
  const withdrawalamt = form.getItem('withdrawalamt');

  if (value === TYPE_WITHDRAWAL) {
    depositamt.setDisabled(true);
    withdrawalamt.setDisabled(false);
    depositamt.setValue(0);
  } else if (value === TYPE_DEPOSIT) {
    depositamt.setDisabled(false);
    withdrawalamt.setDisabled(true);
    withdrawalamt.setValue(0);
  } else {
    depositamt.setDisabled(false);
    withdrawalamt.setDisabled(false);
    form.getItem('description').setValue('');
  }
}

(grid, view, parameters) => {
  AP.registerGridHooks(grid, 'order_invoice', view);
  const form = view.theForm;
  const issotrx = form.getItem('issotrx').getValue();
  const payment = form.getItem('fin_payment_id').getValue();
  // Defer the settling work: at firing time the controller still holds the pre-fetch
  // rows (rowCount=0 phantom) and the selection is not yet committed. Re-read rows AND
  // selection INSIDE the deferral, once the delivered rows + pre-selection have landed.
  // This mirrors classic ordInvDataArrived, which reads getSelectedRecords() after
  // dataArrived (and defers distributeAmount via isc.Timer.setTimeout).
  AP.afterGridSettle(grid, 'order_invoice', () => {
    const selected = grid.getSelectedRecords ? grid.getSelectedRecords() : [];
    if (selected.length > 0) {
      AP.seedPreselectedOrderInvoice(form, grid, selected);
    } else if (issotrx || !payment) {
      AP.distributeAmount(view, form, false);
    } else {
      AP.updateInvOrderTotal(form, grid);
    }
    AP.updateActualExpected(form, view);
  });
}

