  ];
  const SUMMARY_LEVEL = "S";

  const setVisibility = (fieldNames, visible) => {
    fieldNames.forEach((fieldName) => {
      const field = form.getItem(fieldName);
      if (field) {
        if (visible) {
          field.show();
        } else {
          field.hide();
        }
      }
    });
  };

  const accountLevelItem = form.getItem("AccountLevel");
  const accountLevel = accountLevelItem ? accountLevelItem.getValue() : null;

  setVisibility(DIMENSION_FIELDS, accountLevel === SUMMARY_LEVEL);
}

(item, view, form, grid) => {
  const trxtype = AP.trxtype(form);
  const receivedFrom = form.getItem('received_from').getValue();
  const isSOTrx = form.getItem('issotrx').getValue();
  const financialAccount = form.getItem('fin_financial_account_id').getValue();
  const creditToUseGrid = form.getItem('credit_to_use');
  const creditGrid = creditToUseGrid && creditToUseGrid.canvas ? creditToUseGrid.canvas.viewGrid : null;

  if (creditGrid && creditGrid.getSelectedRecords().length > 0) {
    creditGrid.deselectAllRecords();
  }
  AP.recalcDisplayLogicOrReadOnlyLogic(form, view, ['credit_to_use_display_logic']);

  if (trxtype !== '') {
    OB.RemoteCallManager.call(
      'org.openbravo.advpaymentmngt.actionHandler.ReceivedFromPaymentMethodActionHandler',
      { receivedFrom, isSOTrx, financialAccount },
      {},
      (response, data) => {
        if (!data || data.paymentMethodId === null || data.paymentMethodId === undefined) {
          return;
        }
        if (data.paymentMethodId !== '') {
          const paymentMethodItem = form.getItem('fin_paymentmethod_id');
          paymentMethodItem.setValueFromRecord({ id: data.paymentMethodId, _identifier: data.paymentMethodName });
          AP.paymentMethodMulticurrency(view, form, true);
          AP.checkSingleActionAvailable(form);
          AP.refetchOrderInvoiceGrid(form);
          AP.recalcDisplayLogicOrReadOnlyLogic(form, view, ['c_currency_id_readonly_logic']);
        }
      }
    );
    AP.refetchOrderInvoiceGrid(form);
  }
}

(item, view, form, grid) => {
  const RECEIVED_IN = "Received In";
  const PAID_OUT = "Paid Out";

  const itemName = item.name;
  const itemValue = item.getValue();

  if (itemName === RECEIVED_IN) {
    form.getItem(PAID_OUT).setValue(!itemValue);
  }

  if (itemName === PAID_OUT) {
    form.getItem(RECEIVED_IN).setValue(!itemValue);
  }
}

(item, view, form, grid) => {
  const HANDLER =
    'org.openbravo.advpaymentmngt.actionHandler.FundsTransferOnChangeDepositToActionHandler';

  const callback = (response, data) => {
    if (!data || !data.currencyID) {
      return;
    }
    const currencyTo = form.getItem('c_currency_to_id');
    currencyTo.setValueFromRecord({
      id: data.currencyID,
      _identifier: data.currencyISO
    });
    form.redraw();
  };

  OB.RemoteCallManager.call(HANDLER, { accountID: item.getValue() }, {}, callback);
}

(grid, view, parameters) => {
  setLastView(view);
  setAmounts(view);
  grid.onSelectionToggle(recomputeAmounts);
  grid.setColumnOnChange(SETTLEMENT_AMOUNT, onSettlementAmountChange);
}

(item, view, form) => {
  const DOCUMENT_NO_FIELD = "DocumentNo";
  const SHOW_DOCUMENT_NO_FIELD = "showDocumentNo";
  const DOCUMENT_TYPES_WITHOUT_DOC_NO = [
    "361",
    "304",
    "305",
    "362",
    "306",
    "307",
    "8D951A5E22934A819342B97E5755D063",
    "12CD29ED0686428DACEF24B5040A8EA5",
    "21C51C14E7E14F05AE98A0DCFF569C66",
    "8E2E3976B54A46D58752619DDA78E35E",
    "302",
    "257F25CAB32A4009AA45EFCE2ADE5F1C",
    "88BE65DDD6064F25A1837009F7375210",
  ];

  const selectedTypes = item.getValue();
  const documentNo = form.getItem(DOCUMENT_NO_FIELD);
  const showDocumentNo = form.getItem(SHOW_DOCUMENT_NO_FIELD);

  const getSelectedValue = (values) =>
    values && typeof values.get === "function" ? values.get(0) : values && values[0];

  const isSingleSupportedType =
    selectedTypes &&
    selectedTypes.length === 1 &&
    DOCUMENT_TYPES_WITHOUT_DOC_NO.includes(getSelectedValue(selectedTypes));

  if (isSingleSupportedType) {
    showDocumentNo.setValue(false);
    documentNo.setDisabled(false);
  } else {
    showDocumentNo.setValue(true);
    documentNo.setDisabled(true);
    documentNo.clearValue();
  }
}

(item, view, form, grid) => {
  if (item.getValue() === item.oldSelectedValue) {
    return;
  }
  item.oldSelectedValue = item.getValue();
  AP.refetchOrderInvoiceGrid(form);
}

(item, view, form, grid) => {
  const RECIPIENT_FIELD = 'recipient_id';
  const recipientItem = form.getItem(RECIPIENT_FIELD);
  const recipientID = recipientItem ? recipientItem.getValue() : '';

  if (recipientID === '') {
    return;
  }

  const severity = OB.MessageBar.TYPE_WARNING;
  const message = OB.I18N.getLabel('ETVFAC_DATA_ID_ISEMPTY');
  view.messageBar.setMessage(severity, severity.toUpperCase(), message);
}

(item, view, form, grid) => {
  const column1 = form.getItem('Column1').getValue();
  const column2 = form.getItem('Column2').getValue();
  const column3 = form.getItem('Column3').getValue();
  const column4 = form.getItem('Column4').getValue();
  const allSet = column1 && column2 && column3 && column4;
  const ascending = column1 < column2 && column2 < column3 && column3 < column4;
  if (allSet && !ascending) {
    item.setValue('');
    view.messageBar.setMessage(
      isc.OBMessageBar.TYPE_WARNING,
      null,
      OB.I18N.getLabel('OBUIAPP_OverdueNotValid')
    );
  } else {
    view.messageBar.hide();
  }
}

(item, view, form, grid) => {
  const RECEIVED_IN = "Received In";
  const PAID_OUT = "Paid Out";

  const itemName = item.name;
  const itemValue = item.getValue();

  if (itemName === RECEIVED_IN) {
    form.getItem(PAID_OUT).setValue(!itemValue);
  }

  if (itemName === PAID_OUT) {
    form.getItem(RECEIVED_IN).setValue(!itemValue);
  }
}
